const VERB_LEX = {};
(function(){
  const par = t => (t || '').split('; ').filter(Boolean).map(x => { const i = x.indexOf('='), ap = x[0] === '≈'; return { w: x.slice(ap ? 1 : 0, i), pt: x.slice(i + 1), ap }; });   /* ≈ = equivalente aproximado */
  VERB_LEX_TXT.split('\n').forEach(l => {
    const [id, sent, n, a] = l.split('|');
    if(!id) return;
    VERB_LEX[id] = { sent: (sent || '').split('; ').filter(Boolean), n: par(n), a: par(a) };
  });
})();
function lexDe(v){ const x = VERB_LEX[v.id]; return x && (x.sent.length || x.n.length || x.a.length) ? x : null; }

