      rg.forEach(r=>{
        const outro = verbById(r.outro); if(!outro) return;
        const linha = document.createElement('div'); linha.className = 'reg-linha';
        const chip = document.createElement('span'); chip.className = 'reg-par'; chip.textContent = nomeVerbo(outro);
        chip.setAttribute('role', 'button'); chip.tabIndex = 0;
        chip.onclick = () => escolher(outro);
        chip.onkeydown = e => { if(e.key === 'Enter' || e.key === ' '){ e.preventDefault(); escolher(outro); } };
        linha.appendChild(chip);
        const tx = document.createElement('span'); tx.className = 'reg-nuance'; tx.textContent = REG_PARES[r.i][4];
        linha.appendChild(tx);
        rf.appendChild(linha);
      });
      corpo.appendChild(rf);
