/* Rola SÓ a fileira, nunca a página. scrollIntoView (mesmo com block:'nearest') move o
   documento inteiro quando o elemento está fora da vista vertical — era o que fazia o app
   abrir já rolado alguns milhares de pixels. Aqui ajustamos apenas o scrollLeft da faixa. */
function scrollChipIntoRow(row, chip){
  if(!row || !chip) return;
  const rRect = row.getBoundingClientRect(), cRect = chip.getBoundingClientRect();
  if(cRect.left < rRect.left){ row.scrollLeft -= (rRect.left - cRect.left) + 12; }
  else if(cRect.right > rRect.right){ row.scrollLeft += (cRect.right - rRect.right) + 12; }
}
function signalFamilyLabel(cls){
  /* rótulo curto para a fileira de famílias (o texto completo fica no cabeçalho do grupo) */
  const short = { focusMid:"foco", degreeMid:"intensidade", durFam:"duração", freqIndef:"frequência", freqDef:"nº de vezes", perfectAdv:"perfect", timeMid:"tempo (meio)",
    timePoint:"tempo", allFam:"all", timeFam:"time", wholeFam:"whole", everFam:"ever", everyFam:"every",
    againFam:"again", asFam:"as", atFam:"at", fromFam:"from", onFam:"on", overFam:"over", withFam:"with/without", aroundFam:"around", backFam:"back", onceFam:"once", aboutFam:"about", bitFam:"bit/little", mannerFam:"modo", placeFam:"lugar", certaintyFam:"certeza", compareFam:"comparação", seqFam:"sequência", npiFam:"só em neg./perg.", rightFam:"right", underFam:"under", throughFam:"through", withinFam:"within", againstFam:"against", aheadFam:"ahead/behind", updownFam:"up/down", toFam:"to", ofFam:"of", inFam:"in", byFam:"by", forFam:"for", outFam:"out/off",
    splitFam:"partidos", outrosFam:"diversos" };
  return short[cls] || cls;
}
/* ================================================================================
   SELETOR DE PEÇAS POR ENCAIXE — compartilhado pelos motores de tempos e de modais
   Antes, o primeiro nível do filtro era a "família" lexical (at, in, on, by, from…): 37 a 44
   abas por combinação, e 19 delas misturavam funções (o chip "in" juntava "in a hurry",
   "in the garden" e "in 2020"). Agora o primeiro nível é o ENCAIXE — a mesma anatomia da
   referência, nas mesmas cores e na ordem da frase. A forma lexical continua existindo, mas
   como filtro secundário, e só onde a lista é grande.
   ================================================================================ */
const PICK_MAX = 48;          /* peças visíveis antes do "mostrar mais" */
const PICK_FORMA_FORTE = 4;   /* forma com menos peças que isto vai para "outras" */
const PICK_FORMA_MIN = 24;    /* só mostra o filtro por forma em encaixes com pelo menos isto */
const PICK_BUSCA_MIN = 60;    /* só mostra a busca em encaixes realmente grandes */
const PICK_ZONAS = [
  { z:'início', t:'Abre a frase',     d:'seguido de vírgula' },
  { z:'meio',   t:'Antes do verbo',   d:'Será · Só · Sempre · Já · Muito' },
  { z:'fim',    t:'Depois do verbo',  d:'ação → palco → relógio' }
];
function pickChave(sw){ return sw.pl === 'split' ? 'split' : slotOf(sw); }
function pickNome(k){ return k === 'split' ? 'partidos' : END_SLOT_NOME[k]; }

/* o = { st, itens, ativos, desativado, ativo(sw), rival(sw), pick(sw, isActive), limpar(),
         limparAtivo, refresh(), aoMudar() }
   st guarda só a navegação: signalSlot, signalFam (forma), signalBusca, signalMais. */
function renderSlotPicker(el, o){
  const st = o.st;
  const grupos = new Map();
  o.itens.forEach(sw=>{ const k = pickChave(sw); if(!grupos.has(k)) grupos.set(k, []); grupos.get(k).push(sw); });
  const chaves = SLOT_ORDEM.filter(r=>grupos.has(r)).concat(grupos.has('split') ? ['split'] : []);
  if(!chaves.length) return false;

  const ocupados = new Set(o.ativos.map(pickChave));
  if(!grupos.has(st.signalSlot)){
    const a = o.ativos[0];
    st.signalSlot = a ? pickChave(a) : (grupos.has(8) ? 8 : chaves[0]);
    st.signalFam = null; st.signalBusca = ''; st.signalMais = false;
  }
  const dis = o.desativado ? .4 : 1;
  const mudou = ()=>{ if(o.aoMudar) o.aoMudar(); o.refresh(); };

  /* limpar tudo */
  const noneWrap = document.createElement('div'); noneWrap.className = 'signal-row-inner';
  const none = document.createElement('div'); none.className = 'signal-chip';
  none.dataset.active = String(!!o.limparAtivo); none.textContent = o.rotuloLimpar || 'limpar tudo'; none.style.opacity = dis;
  none.onclick = ()=>{ if(!o.desativado) o.limpar(); };
  noneWrap.appendChild(none); el.appendChild(noneWrap);

  /* nível 1: os encaixes, em três zonas */
  const zonas = PICK_ZONAS.concat(grupos.has('split') ? [{ z:'split', t:'Partidos', d:'ocupam meio e fim' }] : []);
  zonas.forEach(Z=>{
    const rs = chaves.filter(k => Z.z === 'split' ? k === 'split' : (k !== 'split' && SLOT_ZONA(k) === Z.z));
    if(!rs.length) return;
    const lab = document.createElement('div'); lab.className = 'pick-zona';
    lab.innerHTML = `${Z.t} <b>${Z.d}</b>`; el.appendChild(lab);
    const row = document.createElement('div'); row.className = 'signal-row-inner wrap-row';
    rs.forEach(k=>{
      const chip = document.createElement('div'); chip.className = 'signal-chip slot-chip';
      chip.dataset.active = String(st.signalSlot === k);
      if(k !== 'split') paintCat(chip, grupos.get(k)[0]);
      const vazio = !!(o.vazios && o.vazios.has(k));
      if(vazio) chip.dataset.vazio = 'true';
      const num = k === 'split' ? '' : `<span class="slot-n">${slotNum(k)}</span>`;
      chip.innerHTML = `${num}${pickNome(k)}${vazio ? '<span class="vazio-q">❓</span>' : `<span class="fam-count">${grupos.get(k).length}</span>`}${ocupados.has(k) ? '<span class="fam-dot"></span>' : ''}`;
      chip.style.opacity = dis;
      chip.onclick = ()=>{ if(o.desativado) return; st.signalSlot = k; st.signalFam = null; st.signalBusca = ''; st.signalMais = false; mudou(); };
      row.appendChild(chip);
    });
    el.appendChild(row);
  });

  /* nível 2: as peças do encaixe aberto */
  const k = st.signalSlot, todos = grupos.get(k);
  const pergunta = (k !== 'split' && typeof SLOT_PERGUNTA !== 'undefined') ? SLOT_PERGUNTA[k] : 'um advérbio que se parte: meio + fim';
  const cab = document.createElement('div'); cab.className = 'signal-group-label';
  cab.textContent = `${pickNome(k)} — ${pergunta}`; el.appendChild(cab);
  if(o.vazios && o.vazios.has(k)){
    /* o encaixe que a palavra interrogativa pergunta fica vazio: é a resposta que vai ocupá-lo */
    const v = document.createElement('div'); v.className = 'signal-hint vazio-nota';
    v.innerHTML = `❓ <b>${o.vazioPor || 'A pergunta'}</b> pergunta justamente por este encaixe — ele fica vazio na frase, porque é a resposta que vai preenchê-lo. Os outros encaixes continuam livres.`;
    el.appendChild(v);
    return true;
  }

  /* formas com poucas peças viram um balde só ("outras"): uma aba com 1 ou 2 itens dá mais
     navegação do que a lista que ela deveria encurtar */
  const contaForma = {}; todos.forEach(s=>{ contaForma[s.cls] = (contaForma[s.cls] || 0) + 1; });
  const fortes = Object.keys(contaForma).filter(c => contaForma[c] >= PICK_FORMA_FORTE);
  const temOutras = Object.keys(contaForma).some(c => contaForma[c] < PICK_FORMA_FORTE);
  const formas = fortes.concat(temOutras && fortes.length ? ['__outras'] : []);
  if(!formas.includes(st.signalFam)) st.signalFam = null;
  const daForma = s => !st.signalFam || (st.signalFam === '__outras' ? contaForma[s.cls] < PICK_FORMA_FORTE : s.cls === st.signalFam);
  if(formas.length > 1 && todos.length >= PICK_FORMA_MIN){
    const fr = document.createElement('div'); fr.className = 'signal-row-inner fam-row';
    const mk = (cls, rotulo, n)=>{
      const b = document.createElement('div'); b.className = 'signal-chip fam-chip';
      b.dataset.active = String(st.signalFam === cls);
      b.innerHTML = `${rotulo}<span class="fam-count">${n}</span>`; b.style.opacity = dis;
      b.onclick = ()=>{ if(o.desativado) return; st.signalFam = cls; st.signalMais = false; mudou(); };
      fr.appendChild(b);
    };
    mk(null, 'todas', todos.length);
    formas.forEach(c => mk(c, c === '__outras' ? 'outras' : signalFamilyLabel(c), todos.filter(s=>c === '__outras' ? contaForma[s.cls] < PICK_FORMA_FORTE : s.cls === c).length));
    el.appendChild(fr);
    scrollChipIntoRow(fr, fr.querySelector('[data-active="true"]'));
  }

  let busca = null;
  if(todos.length >= PICK_BUSCA_MIN){
    busca = document.createElement('input'); busca.type = 'text'; busca.className = 'pick-busca';
    busca.placeholder = `buscar em ${pickNome(k)} (${todos.length})…`; busca.value = st.signalBusca || '';
    busca.setAttribute('autocomplete','off'); busca.setAttribute('autocapitalize','none'); busca.spellcheck = false;
    el.appendChild(busca);
  }

  const lista = document.createElement('div'); lista.className = 'signal-row-inner wrap-row'; el.appendChild(lista);
  const pinta = ()=>{
    lista.innerHTML = '';
    const q = (st.signalBusca || '').trim().toLowerCase();
    const vis = todos.filter(s => daForma(s) && (!q || s.w.toLowerCase().includes(q)));
    const corte = st.signalMais || q ? vis : vis.slice(0, PICK_MAX);
    corte.forEach(sw=>{
      const chip = document.createElement('div'); chip.className = 'signal-chip';
      const isActive = o.ativo(sw);
      chip.dataset.active = String(isActive); chip.textContent = sw.w; paintCat(chip, sw);
      if(!isActive){
        const oc = o.rival(sw);
        if(oc){ chip.dataset.rival = 'true'; chip.title = `Ocupa o mesmo encaixe (${pickNome(k)}) de "${oc.w}" — substitui`; }
      }
      chip.style.opacity = dis;
      chip.onclick = ()=>{ if(!o.desativado) o.pick(sw, isActive); };
      lista.appendChild(chip);
    });
    if(!vis.length){ const v = document.createElement('div'); v.className = 'signal-hint'; v.textContent = 'Nada com esse trecho neste encaixe.'; lista.appendChild(v); }
    if(corte.length < vis.length){
      const m = document.createElement('div'); m.className = 'signal-chip pick-mais';
      m.textContent = `+ ${vis.length - corte.length} peças`;
      m.onclick = ()=>{ st.signalMais = true; pinta(); };
      lista.appendChild(m);
    }
    if(typeof applyA11y === 'function') applyA11y();
  };
  if(busca) busca.addEventListener('input', ()=>{ st.signalBusca = busca.value; pinta(); });
  pinta();
  return true;
}

/* v114: seletor de palavras-sinal da 2ª oração para os motores Modal e Montador. Roda DENTRO de o2Em(C):
   o estado (tempo/aspecto/o2) já é o do motor; st é o objeto de navegação do seletor (encaixe aberto etc.). */
function o2SinaisPicker(el, hint, st){
  const ctx2 = o2Ctx2(), S = state.o2.sl2;
  el.innerHTML = '';
  const lista = o2PalavrasSinal2(ctx2);
  if(!lista.length){
    hint.textContent = ctx2.cap === 'none'
      ? 'A 2ª oração (' + ctx2.tipo.nome + ') ' + (ctx2.motivo || 'tem estrutura fixa') + ': não recebe palavras-sinal. Volte para a Oração 1 para encaixar peças na principal.'
      : 'Nenhuma palavra-sinal cadastrada para o tempo desta 2ª oração.';
    return;
  }
  S.signalMids = o2Sl2().signalMids; S.signalEnds = o2Sl2().signalEnds;
  const ml = () => S.signalMids, el2 = () => S.signalEnds;
  const ocup = sw => (sw.pl === 'end' ? el2() : ml()).find(x => slotOf(x) === slotOf(sw) && x.w !== sw.w) || null;
  renderSlotPicker(el, {
    st, itens: lista, ativos: sortSlots(ml().concat(el2())), desativado: false, vazios: new Set(), vazioPor: null,
    limparAtivo: !(ml().length + el2().length),
    ativo: sw => (sw.pl === 'end' ? el2() : ml()).some(x => x.w === sw.w),
    rival: ocup,
    limpar: () => { S.signalMids = []; S.signalEnds = []; render(); },
    pick: (sw, isActive) => {
      const campo = sw.pl === 'end' ? 'signalEnds' : 'signalMids', atual = S[campo];
      S[campo] = isActive ? atual.filter(x => x.w !== sw.w) : atual.filter(x => slotOf(x) !== slotOf(sw)).concat([sw]);
      render();
    },
    refresh: () => render()
  });
  hint.textContent = (ctx2.cap === 'ends'
    ? 'Esta 2ª oração (' + ctx2.tipo.nome + ') aceita só palavras-sinal de FIM. Valem para o tempo da própria 2ª oração: '
    : 'Encaixes da 2ª oração (' + ctx2.tipo.nome + ') — valem para o tempo dela: ') + TENSE_LABEL[ctx2.tempo] + ' · ' + ASPECT_LABEL[ctx2.aspecto] + ', ' + (ctx2.formato === 'negativa' ? 'negativa' : 'afirmativa') + '. Cada encaixe aceita uma peça.';
}
function buildSignal(){
  const el = document.getElementById('signalRow'); const hint = document.getElementById('signalHint');
  /* v108: foco 2 = os mesmos dials editam a 2ª oração (mala própria, contexto próprio) */
  const foco2 = o2Foco() === 2, ctx2 = foco2 ? o2Ctx2() : null;
  const S = foco2 ? state.o2.sl2 : state;                      /* onde moram os encaixes do foco */
  const FMT = foco2 ? ctx2.formato : state.formato;
  const midList = ()=> Array.isArray(S.signalMids) ? S.signalMids : [];
  const endList = ()=> Array.isArray(S.signalEnds) ? S.signalEnds : [];
  const tt = document.getElementById('sigTitle');
  if(tt) tt.textContent = foco2 ? '⑨ Palavras-sinal — 2ª oração (' + ctx2.tipo.nome + ')' : '⑨ Palavras-sinal por encaixe (opcional)';
  if(foco2){
    el.innerHTML = ""; document.getElementById('signalBankPanel').innerHTML = "";
    const lista = o2PalavrasSinal2(ctx2);
    if(!lista.length){
      hint.textContent = ctx2.cap === 'none'
        ? 'A 2ª oração (' + ctx2.tipo.nome + ') ' + (ctx2.motivo || 'tem estrutura fixa') + ': não recebe palavras-sinal. Volte para a Oração 1 para encaixar peças na principal.'
        : 'Nenhuma palavra-sinal cadastrada para o tempo desta 2ª oração.';
      return;
    }
    S.signalMids = o2Sl2().signalMids; S.signalEnds = o2Sl2().signalEnds;   /* o que não vale mais sai */
    const ocup = (sw)=> (sw.pl === 'end' ? endList() : midList()).find(x => slotOf(x) === slotOf(sw) && x.w !== sw.w) || null;
    renderSlotPicker(el, {
      st: state, itens: lista, ativos: sortSlots(midList().concat(endList())), desativado: false, vazios: new Set(), vazioPor: null,
      limparAtivo: !(midList().length + endList().length),
      ativo: sw => (sw.pl === 'end' ? endList() : midList()).some(x => x.w === sw.w),
      rival: ocup,
      limpar: ()=>{ S.signalMids = []; S.signalEnds = []; render(); },
      pick: (sw, isActive)=>{
        const campo = sw.pl === 'end' ? 'signalEnds' : 'signalMids', atual = campo === 'signalEnds' ? endList() : midList();
        S[campo] = isActive ? atual.filter(x => x.w !== sw.w) : atual.filter(x => slotOf(x) !== slotOf(sw)).concat([sw]);
        render();
      },
      refresh: ()=> render(), aoMudar: ()=>{ bankOpenSignal = false; }
    });
    hint.textContent = ctx2.cap === 'ends'
      ? 'Esta 2ª oração (' + ctx2.tipo.nome + ') aceita só palavras-sinal de FIM (o verbo dela está no subjuntivo/infinitivo, sem lugar para advérbio de meio). Valem para o tempo da própria 2ª oração: ' + TENSE_LABEL[ctx2.tempo] + ' · ' + ASPECT_LABEL[ctx2.aspecto] + '.'
      : 'Encaixes da 2ª oração — valem para o tempo dela (' + TENSE_LABEL[ctx2.tempo] + ' · ' + ASPECT_LABEL[ctx2.aspecto] + ', ' + (ctx2.formato === 'negativa' ? 'negativa' : 'afirmativa') + '). Cada encaixe aceita uma peça.';
    return;
  }
  const key = `${state.tempo}_${state.aspecto}`;
  const comWh = state.formato==='pergunta' && state.whWord && !WH_STATIC[state.whWord];
  /* o sinal partido ocupa meio E fim; com uma interrogativa de adjunto ele atravessaria o encaixe vazio */
  const words = (SIGNAL_WORDS[key] || []).concat(comWh ? [] : (SPLIT_SIGNALS[key] || []))
                  .filter(sw => signalAllowed(sw, state.formato));
  const vazios = comWh ? whVazios(state.whWord) : new Set();
  /* se o formato mudou e o sinal escolhido não vale mais aqui, ele sai de cena */
  if(state.signalSplit && !signalAllowed(state.signalSplit, state.formato)) state.signalSplit = null;
  /* vale também para estados restaurados: um ocupante por encaixe, o resto sai */
  const um = (lista)=>{ const vistos = new Set(); return lista.filter(s=>{
    if(!signalAllowed(s, state.formato)) return false;
    const r = slotOf(s); if(vistos.has(r)) return false; vistos.add(r); return true; }); };
  state.signalEnds = um(endList()).filter(x => !vazios.has(slotOf(x)));
  state.signalMids = um(midList()).filter(x => !vazios.has(slotOf(x)));
  if(comWh) state.signalSplit = null;
  el.innerHTML = "";
  const disabled = !!(state.formato==='pergunta' && state.whWord && WH_STATIC[state.whWord]);

  const ativos = (state.signalSplit ? [state.signalSplit] : []).concat(sortSlots(midList().concat(endList())));
  const ocupante = (sw)=> (sw.pl === 'split') ? null
      : (sw.pl === 'end' ? endList() : midList()).find(s => slotOf(s) === slotOf(sw) && s.w !== sw.w) || null;
  const ok = renderSlotPicker(el, {
    st: state, itens: words, ativos, desativado: disabled,
    vazios, vazioPor: state.whWord,
    limparAtivo: !ativos.length,
    ativo: sw => sw.pl === 'split' ? !!(state.signalSplit && state.signalSplit.w === sw.w)
                : (sw.pl === 'end' ? endList() : midList()).some(s => s.w === sw.w),
    rival: ocupante,
    limpar: ()=>{ state.signalMids = []; state.signalEnds = []; state.signalSplit = null; render(); },
    pick: (sw, isActive)=>{
      if(sw.pl === 'split'){
        /* o partido ocupa meio E fim, então limpa os dois slots simples */
        state.signalSplit = isActive ? null : sw; state.signalMids = []; state.signalEnds = [];
      } else {
        /* Um ocupante por encaixe: outra peça do MESMO encaixe substitui a anterior (dois
           lugares não se somam); encaixes diferentes convivem — inclusive vários do meio. */
        const campo = sw.pl === 'end' ? 'signalEnds' : 'signalMids';
        const atual = campo === 'signalEnds' ? endList() : midList();
        state[campo] = isActive ? atual.filter(s => s.w !== sw.w)
                                : atual.filter(s => slotOf(s) !== slotOf(sw)).concat([sw]);
        state.signalSplit = null;
      }
      render();
    },
    refresh: ()=> render(),
    aoMudar: ()=>{ bankOpenSignal = false; }
  });
  if(!ok){ hint.textContent = "Nenhuma palavra-sinal cadastrada para esta combinação ainda."; return; }

  /* resumo do que está ativo — some quando nada está selecionado, e cada etiqueta remove só o seu */
  const etiquetas = [];
  if(state.signalSplit) etiquetas.push({label:state.signalSplit.w, pos:"meio + fim", sw:state.signalSplit, clear:()=>{ state.signalSplit=null; }});
  sortSlots(midList().concat(endList())).forEach(s=> etiquetas.push({
    label: s.w, pos: `${slotNum(slotOf(s))}. ${END_SLOT_NOME[slotOf(s)] || adjKind(s.cls, s.w)}`, sw: s,
    clear: ()=>{ state.signalMids = midList().filter(x=>x.w!==s.w); state.signalEnds = endList().filter(x=>x.w!==s.w); }
  }));
  if(etiquetas.length && !disabled){
    const box = document.createElement('div'); box.className='signal-active';
    const cap = document.createElement('span'); cap.textContent = "ativos:"; box.appendChild(cap);
    etiquetas.forEach(a=>{
      const tag = document.createElement('span'); tag.className='tagx';
      tag.innerHTML = `<b>${a.label}</b><span>${a.pos}</span>✕`;
      paintCat(tag, a.sw);
      tag.onclick = ()=>{ a.clear(); render(); };
      box.appendChild(tag);
    });
    el.appendChild(box);
  }

  buildSignalBank();
  hint.textContent = disabled ? "How much / How many são exemplos fixos — remova a palavra interrogativa para usar sinais."
    : comWh ? (vazios.size ? `Com "${state.whWord}" o encaixe marcado com ❓ fica vazio (é a resposta); os demais aceitam peças normalmente. Ao escolher a interrogativa, as peças desse encaixe saem.`
                           : `"${state.whWord}" não esvazia nenhum encaixe de advérbio — todos continuam livres.`)
    : "Escolha o encaixe e depois a peça. Cada encaixe aceita uma peça; encaixes diferentes se somam — dá para montar a frase inteira.";
}
function buildFormato(){
  const el = document.getElementById('formatoRow'); el.innerHTML="";
  FORMATOS.forEach(f=>{
    const s = document.createElement('div'); s.className='formato-switch';
    s.dataset.kind=f; s.dataset.active=(state.formato===f);
    s.innerHTML = `<div class="lamp"></div><div class="lbl">${FORMATO_LABEL[f]}</div>`;
    s.onclick = ()=>{ state.formato=f; if(f!=='pergunta') state.whWord=null; render(); };
    el.appendChild(s);
  });
}
function buildWh(){
  const el = document.getElementById('whGrid'); const hint = document.getElementById('whHint');
  el.innerHTML="";
  const noneWrap = document.createElement('div'); noneWrap.className='signal-row-inner';
  const none = document.createElement('div'); none.className='signal-chip';
  none.dataset.active = (state.whWord===null); none.textContent = "nenhuma (sim/não)";
  none.onclick = ()=>{ state.whWord=null; render(); };
  noneWrap.appendChild(none); el.appendChild(noneWrap);

  /* v148: grupos novos; cada chip só aparece onde a pergunta existe (categoria, verbo transitivo, sujeito existencial) */
  const vWh = state.categoria === 'fact' ? verbById(state.verbo) : null, sWh = sujAtivo();
  const groups = [ ["Sujeito (sem inversão)", WH_SUBJECT], ["Objeto (com inversão — o complemento é a resposta)", WH_OBJETO], ["Circunstância (com inversão)", WH_ADJUNCT.concat(WH_ADJ_MAIS)],
    ["Quantidade", WH_QUANTITY], ["Preposição no fim", WH_PREP_FIM], ["Estruturas especiais", WH_ESPECIAIS] ]
    .map(([label, list]) => [label, list.filter(w => whDisponivel(w, state.categoria, vWh, sWh))]).filter(g => g[1].length);
  groups.forEach(([label, list])=>{
    const lab = document.createElement('div'); lab.className='wh-group-label'; lab.textContent = label; el.appendChild(lab);
    const wrap = document.createElement('div'); wrap.className='signal-row-inner';
    list.forEach(w=>{
      const chip = document.createElement('div'); chip.className='signal-chip';
      chip.dataset.active = (state.whWord===w); chip.textContent = w;
      chip.onclick = ()=>{ if(state.whWord !== w) state.whMolde = null; state.whWord=w; state.formato='pergunta'; render(); };
      if((WH_MOLDES[w] || []).length) chip.title = 'Tem estruturas ligadas (aparecem ao escolher)';
      wrap.appendChild(chip);
    });
    el.appendChild(wrap);
  });
  /* v149: estruturas ligadas à interrogativa escolhida ("How long" → does it take… to) */
  const moldes = state.whWord ? whMoldesDisponiveis(state.whWord, state.categoria) : [];
  if(moldes.length){
    const lab = document.createElement('div'); lab.className='wh-group-label'; lab.id = 'whMoldeLabel'; lab.textContent = 'Estruturas ligadas a ' + ((WH_X[state.whWord] || {}).w || state.whWord); el.appendChild(lab);
    const wrap = document.createElement('div'); wrap.className='signal-row-inner wrap-row'; wrap.id = 'whMoldeRow';
    const mk = (txt, k) => { const c = document.createElement('div'); c.className='signal-chip'; c.dataset.active = String((state.whMolde || null) === k); c.textContent = txt; c.onclick = ()=>{ state.whMolde = k; render(); }; wrap.appendChild(c); };
    mk('pergunta direta', null);
    moldes.forEach(m => mk(((WH_X[state.whWord] || {}).w || state.whWord) + ' ' + m.rot, m.k));
    el.appendChild(wrap);
  }
  hint.textContent = "A interrogativa esvazia o encaixe que ela pergunta (Where→lugar, When→tempo, How→modo, How long→duração, How often→periodicidade e frequência); os outros encaixes seguem livres no dial ⑨. Cada interrogativa traz uma nota explicativa no quadro 💡. As de objeto só aparecem com verbos que aceitam objeto direto. Combinações servem para entender a estrutura — nem toda frase é 100% natural.";
}
/* Alguns advérbios do inglês são de POLARIDADE NEGATIVA: só existem em frases negativas
   ou interrogativas. "I don't work at all" e "Do you work at all?" são naturais;
   "I work at all" não existe. O campo `only` marca esses sinais, e o dial ⑨ só os oferece
   nos formatos onde são gramaticais — em vez de deixar o motor produzir inglês inválido. */
/* ---- Ordem dos adjuntos no fim da frase ----
   Quando vários coexistem, o inglês segue uma ordem canônica — grau → modo → lugar →
   frequência → duração → tempo → sequência ("I work hard at home every day"). O usuário
   escolhe livremente; o motor ordena. O português segue a mesma sequência, o que torna a
   regra ensinável nas duas línguas ao mesmo tempo. */
/* Cada POSIÇÃO da ordem canônica aceita um ocupante. Duas expressões do mesmo encaixe
   competem ("everywhere there" — dois lugares); de encaixes diferentes, somam
   ("a bit quickly", "twice yesterday"), ainda que sejam da mesma cor. Por isso o limite
   é por encaixe, e não um teto global: são 15 posições que se complementam. */
const END_SLOT_NOME = { 1:'grau', 2:'modo', 3:'comparação', 4:'lugar', 5:'periodicidade',
                        6:'duração', 7:'aproximação', 8:'tempo', 9:'sequência', 10:'polaridade',
                        11:'certeza', 12:'foco', 13:'frequência', 14:'fase', 15:'intensidade' };
const END_RANK = {
  bitFam:1, mannerFam:2, compareFam:3, placeFam:4,
  freqDef:5, everyFam:5, freqIndef:5,
  allFam:6, wholeFam:6, durFam:6, aboutFam:7,
  timePoint:8, timeFam:8, withinFam:8, onceFam:8, againFam:8, everFam:8,
  seqFam:9, npiFam:10
};
function endRank(sw){
  /* a posição segue a categoria real: "by heart" (modo) vem antes de "at home" (lugar),
     que vem antes de "by then" (tempo) — mesmo vindo de famílias diferentes */
  const k = adjKind(sw.cls, sw.w);
  if(k === 'como') return END_RANK[sw.cls] && END_RANK[sw.cls] <= 3 ? END_RANK[sw.cls] : 2;
  if(k === 'onde') return 4;
  return END_RANK[sw.cls] || 8;
}
function sortEnds(list){ return list.slice().sort((a,b)=> endRank(a)-endRank(b)); }
